package net.civeira.phylax.features.notification.smtpoutboundconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class HostVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property host of smtp outbound config ")
  void test_host_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> HostVO.tryFrom(null));
    Assertions.assertEquals("one", HostVO.from("one").getHost());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> HostVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", HostVO.from("one").toString());
  }
}
